pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newLog) public {
        vm.assume(actor != address(0));
        vm.assume(newLog != address(0));
        // finalize configuration: after Initialized(), the guard makes
        // SetLogFile permanently revert in the reference contract
        vm.prank(actor);
        c.Initialized();
        bool ok;
        vm.prank(actor);
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        // GENERAL RULE: after initialization, SetLogFile must ALWAYS revert
        assertTrue(!ok);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 1e30);

        LogFile lf = new LogFile();
        c.SetLogFile(address(lf));

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        // General rule: once the log file is configured, every deposit is
        // recorded in that log's history (exactly one entry).
        assertTrue(lf.History().length == 1, "deposit must be logged after SetLogFile");
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string Data;
        uint Val;
        uint Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

